,["jobend"]=[[fb16rw03lg]]},["rlt_text11"]={["arg1"]=[[文本输出]],["arg2"]=[[你抚摸着壁画，突然发现一只鹦鹉的眼睛有些问题，你摸了摸，按了下去，一道暗门隆隆打开，里面是间密室，你走了进去。]],["id"]=[[rlt_text11]]},["rlt_text1100"]={["arg1"]=[[文本输出]],["arg2"]=[[你拿起桌上的一幅画，上面有一些未干的墨痕。]],["id"]=[[rlt_text1100]],["jobstart"]=[[fb16rw07]]},["rlt_text12"]={["arg1"]=[[文本输出]],["arg2"]=[[你拿起旁边的柴刀劈起了柴火，劈了许久，你有些累了。]],["id"]=[[rlt_text12]]},["rlt_text1200"]={["arg1"]=[[文本输出]],["arg2"]=[[你将其中一摞书抱在怀里。]],["id"]=[[rlt_text1200]]},["rlt_text1201"]={["arg1"]=[[文本输出]],["arg2"]=[[怀中已经抱着一摞书，没法再抱更多。]],["id"]=[[rlt_text1201]]},["rlt_text1202"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1202]]},["rlt_text13"]={["arg1"]=[[文本输出]],["arg2"]=[[你拨开木柴堆，在里面发现了一个略有不同的柴火，原来是一简竹简。]],["id"]=[[rlt_text13]]},["rlt_text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你仔细阅读竹简，但是这上面的文字十分难懂，你无法看透。]],["id"]=[[rlt_text14]]},["rlt_text15"]={["arg1"]=[[文本输出]],["arg2"]=[[你细细地查阅石壁，虽然这些文字古老而难懂，但你还是能够琢磨出一些意思出来，原来这是一篇内功心法的口诀。]],["id"]=[[rlt_text15]],["jobend"]=[[fb16rw02lg]]},["rlt_text16"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL挥毫客：这..这难道是张旭的率意贴，在下无以为报，我这平生所学武功尽在这一套裴将军诗杖法中，这就传与少侠吧。]],["id"]=[[rlt_text16]],["jobend"]=[[fb16rw06lg]]},["rlt_text17"]={["arg1"]=[[文本输出]],["arg2"]=[[你在红花里发现一颗朱果，这可是好东西呀，你看着旁边没人把朱果收了起来。]],["id"]=[[rlt_text17]]},["rlt_text18"]={["arg1"]=[[文本输出]],["arg2"]=[[你打开黄石谱，这是一本琴谱，你读着读着，似乎可以从里面发现一些其他的东西。这本书让你领悟颇深。]],["id"]=[[rlt_text18]]},["rlt_text19"]={["arg1"]=[[文本输出]],["arg2"]=[[你轻轻的掀开厚厚的松针，但是什么都没有。]],["id"]=[[rlt_text19]]},["rlt_text2"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL家丁：少侠果然有两下子，不过前方还有我庄高手，少侠可得当心了。]],["id"]=[[rlt_text2]]},["rlt_text20"]={["arg1"]=[[文本输出]],["arg2"]=[[你轻轻的掀开厚厚的松针，哇，下面居然有一本书。]],["id"]=[[rlt_text20]]},["rlt_text21"]={["arg1"]=[[文本输出]],["arg2"]=[[WHT对弈客受伤逃走了。]],["id"]=[[rlt_text21]]},["rlt_text22"]={["arg1"]=[[文本输出]],["arg2"]=[[WHT鼓笙客受伤逃走了。]],["id"]=[[rlt_text22]]},["rlt_text23"]={["arg1"]=[[文本输出]],["arg2"]=[[WHT挥毫客受伤逃走了。]],["id"]=[[rlt_text23]]},["rlt_text24"]={["arg1"]=[[文本输出]],["arg2"]=[[你双脚用力一蹬，平地跳起丈许，轻盈地落在书架顶处，取下那件包裹，里面却是一件血棋衣。]],["id"]=[[rlt_text24]]},["rlt_text25"]={["arg1"]=[[文本输出]],["arg2"]=[[你双脚奋力一蹬，但你的轻功太弱，还未到书架顶处便已落了下来。]],["id"]=[[rlt_text25]]},["rlt_text26"]={["arg1"]=[[文本输出]],["arg2"]=[[你躺在床上美美地睡了一觉。]],["id"]=[[rlt_text26]]},["rlt_text27"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL鼓笙客：这..这曲子，此曲只应天上有，人间能得几回闻，这谱你当真送我？那老夫也不藏私了，这是老夫绝学“五韵七弦剑”如今就传与少侠吧。]],["id"]=[[rlt_text27]],["jobend"]=[[fb16rw05lg]]},["rlt_text28"]={["arg1"]=[[文本输出]],["arg2"]=[[你看着石壁上的文字，十分难懂，许久都摸不着头绪。]],["id"]=[[rlt_text28]]},["rlt_text29"]={["arg1"]=[[文本输出]],["arg2"]=[[这石壁上的功法你已经学会了，无需再学了。]],["id"]=[[rlt_text29]],["jobend"]=[[fb16rw02lg]]},["rlt_text3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL宇高驰：少侠好俊的功夫，在下佩服。]],["id"]=[[rlt_text3]]},["rlt_text30"]={["arg1"]=[[文本输出]],["arg2"]=[[成功将王涧歧缉拿，可去任务里面的历练处领取奖励了。]],["id"]=[[rlt_text30]]},["rlt_text31"]={["arg1"]=[[文本输出]],["arg2"]=[[成功将宋文成缉拿，可去任务里面的历练处领取奖励了。]],["id"]=[[rlt_text31]]},["rlt_text32"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：唉，没想到你对此一窍不通，也罢，我听闻你与我手下过了几招，武功还不错，来吧，让我见识一下。]],["id"]=[[rlt_text32]]},["rlt_text33"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：你倒是有些才学，我听闻你连败我两名手下，想必武功不弱，来来来，咱们过两招。]],["id"]=[[rlt_text33]]},["rlt_text34"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：不错不错，看来你倒也熟知酒道，听闻你武功不弱，来，咱们过过手。]],["id"]=[[rlt_text34]]},["rlt_text35"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：哈哈，看来阁下也精通酒道，倒是与我相像的很呐，我刚听我手下说你武功不错，来，咱们比试比试。]],["id"]=[[rlt_text35]]},["rlt_text36"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text36]]},["rlt_text37"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text37]]},["rlt_text38"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text38]]},["rlt_text39"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text39]]},["rlt_text4"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL范姜云：阁下武功超凡，请进。]],["id"]=[[rlt_text4]]},["rlt_text5"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：色比凉浆犹嫩，香同甘露永春，当真是好酒，阁下想必也是好酒之人，我且出几道题目，不知阁下可能答得上来？]],["id"]=[[rlt_text5]]},["rlt_text6"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL妙笔客：阁下武功果然厉害。]],["id"]=[[rlt_text6]],["jobend"]=[[fb16rw01]]},["rlt_text600"]={["arg1"]=[[文本输出]],["arg2"]=[[你将木炭放于锅下并点燃了木炭。]],["id"]=[[rlt_text600]]},["rlt_text601"]={["arg1"]=[[文本输出]],["arg2"]=[[你将材料一一放入锅内。]],["id"]=[[rlt_text601]]},["rlt_text602"]={["arg1"]=[[文本输出]],["arg2"]=[[你身上的木炭不够。]],["id"]=[[rlt_text602]]},["rlt_text603"]={["arg1"]=[[文本输出]],["arg2"]=[[你身上没有羊肉汤。]],["id"]=[[rlt_text603]]},["rlt_text604"]={["arg1"]=[[文本输出]],["arg2"]=[[你将山泉倒入锅中。]],["id"]=[[rlt_text604]]},["rlt_text605"]={["arg1"]=[[文本输出]],["arg2"]=[[你身上的山泉不够。]],["id"]=[[rlt_text605]]},["rlt_text606"]={["arg1"]=[[文本输出]],["arg2"]=[[火锅已然做好，香气四溢，不禁让人食欲大开，你迫不及待地将锅子连并食材一起端起！]],["id"]=[[rlt_text606]]},["rlt_text7"]={["arg1"]=[[文本输出]],["arg2"]=[[WHT妙笔客受伤逃走了。]],["id"]=[[rlt_text7]]},["rlt_text8"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL鼓笙客：少侠你要做什么！此人乃是上代魔教教主，若是放他出去，这江湖上恐怕又要大乱了，快快住手！
